// ---- 08-slot-samples.js: real recorded slot-machine sounds
// Recorded sounds rather than a synthesiser, because a cabinet is a physical thing and a synthesiser
// does not sound like one.
// Eight short clips, mono 22 kHz Vorbis, embedded as data URIs so the plugin stays one file and the
// install keeps working. Source: Mixkit free sound effects (Mixkit License - free to use in a
// project, no attribution required; credited in THIRD-PARTY-NOTICES.md anyway).
//
// Titles, in order: Coins handling, Magical coin win, Slot machine win alert, Payout award ding,
// Payout award, Slot machine win, Slot machine win siren, Slot machine wheel.
const SM_SFX = {
  coin: 'data:audio/ogg;base64,',
  coinwin: 'data:audio/ogg;base64,',
  winalert: 'data:audio/ogg;base64,',
  ding: 'data:audio/ogg;base64,',
  payout: 'data:audio/ogg;base64,',
  win: 'data:audio/ogg;base64,',
  siren: 'data:audio/ogg;base64,',
  wheel: 'data:audio/ogg;base64,'
}

// Decoded buffers are kept for the life of the page: a ching cascade asks for the same clip twenty
// times and must not decode it twenty times.
const SM_SFX_CACHE = {}

async function smSfxBuffer(name) {
  if (SM_SFX_CACHE[name]) return SM_SFX_CACHE[name]
  const uri = SM_SFX[name]
  if (!uri) return null
  const ctx = typeof soundAudio === 'function' ? soundAudio() : null
  if (!ctx || !ctx.decodeAudioData) return null
  try {
    // Decode the data URI straight into bytes: no network, no CSP surface, one less failure mode
    // than a network request for a data: URL.
    const base64 = uri.slice(uri.indexOf(',') + 1)
    const binary = atob(base64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
    const buffer = await new Promise((resolve, reject) => {
      const answer = ctx.decodeAudioData(bytes.buffer, resolve, reject)
      if (answer && typeof answer.then === 'function') answer.then(resolve).catch(reject)
    })
    if (!buffer) return null
    SM_SFX_CACHE[name] = buffer
    return buffer
  } catch {
    return null
  }
}

// Play one clip with a little variation so repeated coins are not one machine-gun sample: rate
// shifts the pitch and length, gain varies, delay offsets it.
function smSfxPlay(name, options) {
  if (typeof gamesSoundOn === 'function' && !gamesSoundOn()) return Promise.resolve(false)
  const ctx = typeof soundAudio === 'function' ? soundAudio() : null
  if (!ctx) return Promise.resolve(false)
  const rate = Math.max(0.5, Math.min(2.2, Number((options && options.rate) || 1)))
  // The master volume from the settings rides on every clip as well as every synth voice.
  const master = typeof gamesVolume === 'function' ? gamesVolume() : 1
  const gain = Math.max(0, Math.min(2, Number((options && options.gain) || 1))) * master
  const delay = Math.max(0, Number((options && options.delay) || 0))
  return smSfxBuffer(name).then(buffer => {
    if (!buffer) return false
    try {
      const source = ctx.createBufferSource()
      const amp = ctx.createGain()
      // Soften the clip: recorded slot effects are mastered loud and bright, which is abrasive at
      // conversation volume. A gentle low-pass takes the glare off the metal, a 6 ms ramp removes
      // the click at each edge, and the overall level sits under the voice.
      const softener = ctx.createBiquadFilter()
      softener.type = 'lowpass'
      softener.frequency.value = 6400
      softener.Q.value = 0.4
      source.buffer = buffer
      source.playbackRate.value = rate
      const at = ctx.currentTime + 0.005 + delay
      amp.gain.setValueAtTime(0.0001, at)
      amp.gain.linearRampToValueAtTime(gain * 0.38, at + 0.008)
      amp.gain.setValueAtTime(gain * 0.38, at + Math.max(0.02, buffer.duration / rate - 0.01))
      amp.gain.linearRampToValueAtTime(0.0001, at + buffer.duration / rate)
      source.connect(softener).connect(amp).connect(typeof soundBus === 'function' ? soundBus(ctx) : ctx.destination)
      source.start(at)
      return true
    } catch {
      return false
    }
  })
}

// A sample when it loads, the synth when it does not: an older runtime, a blocked decode or a
// missing clip still makes a sound rather than silence.
function smSfxOr(name, options, fallback) {
  smSfxPlay(name, options).then(ok => { if (!ok && typeof fallback === 'function') fallback() }).catch(() => {
    if (typeof fallback === 'function') fallback()
  })
}
